WITH joined AS (SELECT a.*, o.channel, o.status AS order_status FROM shipments a LEFT JOIN orders o ON a.order_id = o.id), kept_keys AS (SELECT id FROM joined EXCEPT ALL SELECT id FROM shipments WHERE order_id = 11), kept_rows AS (SELECT s.* FROM joined s JOIN kept_keys k ON s.id = k.id), with_window AS (SELECT e.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM kept_rows e LEFT JOIN promotions pr ON COALESCE(e.channel, 'web') = pr.channel AND e.shipped_date >= pr.starts_on AND e.shipped_date < pr.ends_on + INTERVAL '7' DAY), daily AS (SELECT CASE WHEN promo_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS promo_id_tier, carrier, order_status, PERCENTILE_APPROX(discount_pct, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_quartiles, COUNT(*) FILTER (WHERE order_status = 'SHIPPED') AS shipped_rows FROM with_window GROUP BY CASE WHEN promo_id >= 8 THEN 'LARGE' ELSE 'SMALL' END, carrier, order_status) SELECT promo_id_tier, carrier, order_status, discount_pct_quartiles, shipped_rows FROM daily ORDER BY shipped_rows DESC
